1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Bring Back Fable 5 — Community Distillation Project</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600&display=swap" rel="stylesheet">
9	<style>
10	:root {
11	  --bg: #0d1117;
12	  --bg-warm: #161b22;
13	  --card: #161b22;
14	  --card-hover: #1c2129;
15	  --border: #30363d;
16	  --border-light: #21262d;
17	  --text: #c9d1d9;
18	  --text-secondary: #8b949e;
19	  --text-muted: #484f58;
20	  --accent: #58a6ff;
21	  --green: #3fb950;
22	  --orange: #d29922;
23	  --red: #f85149;
24	  --purple: #bc8cff;
25	  --shadow-sm: 0 1px 3px rgba(0,0,0,0.3);
26	  --shadow-md: 0 4px 12px rgba(0,0,0,0.35);
27	  --shadow-lg: 0 8px 32px rgba(0,0,0,0.5);
28	  --radius: 12px;
29	  --radius-sm: 8px;
30	  --radius-xs: 6px;
31	  --transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
32	}
33	* { margin: 0; padding: 0; box-sizing: border-box; }
34	html { scroll-behavior: smooth; }
35	body {
36	  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
37	  background: var(--bg);
38	  color: var(--text);
39	  line-height: 1.6;
40	  -webkit-font-smoothing: antialiased;
41	}
42	
43	/* ─── Shell ─── */
44	.shell { max-width: 1100px; margin: 0 auto; padding: 2rem; }
45	
46	/* ─── Hero ─── */
47	.hero {
48	  padding: 3.5rem 0 2.5rem;
49	  text-align: center;
50	  position: relative;
51	}
52	.hero::before {
53	  content: '';
54	  position: absolute;
55	  top: -80px; left: 50%;
56	  transform: translateX(-50%);
57	  width: 600px; height: 600px;
58	  background: radial-gradient(ellipse, rgba(88,166,255,0.06) 0%, transparent 70%);
59	  pointer-events: none;
60	}
61	.hero-eyebrow {
62	  display: inline-flex;
63	  align-items: center;
64	  gap: 8px;
65	  padding: 5px 14px;
66	  border-radius: 100px;
67	  background: rgba(248,81,73,0.1);
68	  border: 1px solid rgba(248,81,73,0.25);
69	  font-size: 0.76rem;
70	  font-weight: 600;
71	  color: var(--red);
72	  text-transform: uppercase;
73	  letter-spacing: 0.06em;
74	  margin-bottom: 1.25rem;
75	}
76	.hero-eyebrow .pulse {
77	  width: 8px; height: 8px;
78	  border-radius: 50%;
79	  background: var(--red);
80	  animation: pulse 2s ease-in-out infinite;
81	}
82	@keyframes pulse {
83	  0%, 100% { opacity: 1; box-shadow: 0 0 0 0 rgba(248,81,73,0.4); }
84	  50% { opacity: 0.7; box-shadow: 0 0 0 6px rgba(248,81,73,0); }
85	}
86	.hero h1 {
87	  font-size: clamp(2rem, 5vw, 3.2rem);
88	  font-weight: 900;
89	  letter-spacing: -0.035em;
90	  line-height: 1.15;
91	  margin-bottom: 1rem;
92	}
93	.hero h1 .fable { color: var(--accent); }
94	.hero h1 .strike {
95	  text-decoration: line-through;
96	  text-decoration-color: var(--red);
97	  text-decoration-thickness: 3px;
98	  opacity: 0.45;
99	}
100	.hero-sub {
101	  font-size: 1.05rem;
102	  color: var(--text-secondary);
103	  max-width: 620px;
104	  margin: 0 auto 2rem;
105	  line-height: 1.7;
106	}
107	.hero-sub strong { color: var(--text); font-weight: 600; }
108	
109	/* ─── Stat Row ─── */
110	.stat-row {
111	  display: grid;
112	  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
113	  gap: 12px;
114	  margin-bottom: 1.75rem;
115	}
116	.stat-pill {
117	  background: var(--card);
118	  border: 1px solid var(--border);
119	  border-radius: var(--radius-sm);
120	  padding: 1.1rem 1.25rem;
121	  transition: box-shadow var(--transition), transform var(--transition);
122	}
123	.stat-pill:hover { box-shadow: var(--shadow-md); transform: translateY(-1px); }
124	.stat-pill .label {
125	  font-size: 0.7rem; font-weight: 600; text-transform: uppercase;
126	  letter-spacing: 0.06em; color: var(--text-muted); margin-bottom: 4px;
127	}
128	.stat-pill .value { font-size: 1.5rem; font-weight: 800; letter-spacing: -0.02em; }
129	.stat-pill .value.green { color: var(--green); }
130	.stat-pill .value.orange { color: var(--orange); }
131	.stat-pill .value.accent { color: var(--accent); }
132	.stat-pill .value.purple { color: var(--purple); }
133	.stat-pill .sub { font-size: 0.74rem; color: var(--text-secondary); margin-top: 2px; }
134	
135	/* ─── Progress Bar ─── */
136	.progress-section {
137	  background: var(--card);
138	  border: 1px solid var(--border);
139	  border-radius: var(--radius);
140	  padding: 1.5rem;
141	  margin-bottom: 1.75rem;
142	}
143	.progress-header {
144	  display: flex;
145	  justify-content: space-between;
146	  align-items: baseline;
147	  margin-bottom: 10px;
148	}
149	.progress-header h3 {
150	  font-size: 0.95rem;
151	  font-weight: 700;
152	}
153	.progress-header .pct {
154	  font-size: 0.88rem;
155	  font-weight: 700;
156	  color: var(--green);
157	  font-family: 'JetBrains Mono', monospace;
158	}
159	.progress-track {
160	  width: 100%;
161	  height: 10px;
162	  background: var(--bg);
163	  border-radius: 100px;
164	  overflow: hidden;
165	  position: relative;
166	}
167	.progress-fill {
168	  height: 100%;
169	  border-radius: 100px;
170	  background: linear-gradient(90deg, var(--green), var(--accent));
171	  width: 0%;
172	  transition: width 1.5s cubic-bezier(0.4, 0, 0.2, 1);
173	}
174	.progress-labels {
175	  display: flex;
176	  justify-content: space-between;
177	  margin-top: 8px;
178	  font-size: 0.72rem;
179	  color: var(--text-muted);
180	}
181	.milestone-row {
182	  display: flex;
183	  gap: 8px;
184	  margin-top: 14px;
185	  flex-wrap: wrap;
186	}
187	.milestone {
188	  display: inline-flex;
189	  align-items: center;
190	  gap: 5px;
191	  padding: 4px 10px;
192	  border-radius: 100px;
193	  font-size: 0.72rem;
194	  font-weight: 600;
195	  border: 1px solid var(--border);
196	  color: var(--text-secondary);
197	  background: var(--bg);
198	}
199	.milestone.reached { border-color: var(--green); color: var(--green); background: rgba(63,185,80,0.08); }
200	.milestone .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
201	
202	/* ─── Timeline ─── */
203	.section { margin-bottom: 1.75rem; }
204	.section-head {
205	  display: flex; align-items: center; justify-content: space-between;
206	  margin-bottom: 0.85rem;
207	}
208	.section-head h2 { font-size: 1.15rem; font-weight: 700; letter-spacing: -0.02em; }
209	.section-head .badge {
210	  font-size: 0.72rem; font-weight: 600; padding: 3px 10px; border-radius: 100px;
211	  background: var(--bg-warm); color: var(--text-secondary); border: 1px solid var(--border);
212	}
213	
214	.timeline {
215	  background: var(--card);
216	  border: 1px solid var(--border);
217	  border-radius: var(--radius);
218	  overflow: hidden;
219	}
220	.tl-row {
221	  display: grid;
222	  grid-template-columns: 100px 1fr auto;
223	  align-items: center;
224	  gap: 14px;
225	  padding: 13px 18px;
226	  border-bottom: 1px solid var(--border-light);
227	  transition: background var(--transition);
228	}
229	.tl-row:last-child { border-bottom: none; }
230	.tl-row:hover { background: var(--card-hover); }
231	.tl-date {
232	  font-family: 'JetBrains Mono', monospace;
233	  font-size: 0.78rem;
234	  color: var(--text-muted);
235	  display: flex;
236	  align-items: center;
237	  gap: 8px;
238	}
239	.tl-date::before {
240	  content: '';
241	  width: 8px; height: 8px;
242	  border-radius: 50%;
243	  flex-shrink: 0;
244	  box-shadow: 0 0 0 3px rgba(255,255,255,0.04);
245	}
246	.tl-date.green::before { background: var(--green); }
247	.tl-date.red::before { background: var(--red); }
248	.tl-date.orange::before { background: var(--orange); }
249	.tl-date.accent::before { background: var(--accent); }
250	.tl-date.purple::before { background: var(--purple); }
251	.tl-event { font-size: 0.88rem; font-weight: 600; letter-spacing: -0.01em; }
252	.tl-tag {
253	  display: inline-flex;
254	  align-items: center;
255	  padding: 3px 10px;
256	  border-radius: 4px;
257	  font-size: 0.71rem;
258	  font-weight: 600;
259	  white-space: nowrap;
260	}
261	.tl-tag.ship { background: rgba(63,185,80,0.12); color: var(--green); }
262	.tl-tag.kill { background: rgba(248,81,73,0.12); color: var(--red); }
263	.tl-tag.community { background: rgba(88,166,255,0.12); color: var(--accent); }
264	.tl-tag.warn { background: rgba(210,153,34,0.12); color: var(--orange); }
265	
266	/* ─── How It Works ─── */
267	.how-grid {
268	  display: grid;
269	  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
270	  gap: 14px;
271	  margin-bottom: 1.75rem;
272	}
273	.how-card {
274	  background: var(--card);
275	  border: 1px solid var(--border);
276	  border-radius: var(--radius);
277	  padding: 1.4rem;
278	  transition: box-shadow var(--transition), border-color var(--transition);
279	  position: relative;
280	}
281	.how-card:hover { box-shadow: var(--shadow-sm); border-color: var(--accent); }
282	.how-card .step-num {
283	  display: inline-flex;
284	  align-items: center;
285	  justify-content: center;
286	  width: 28px; height: 28px;
287	  border-radius: 50%;
288	  background: rgba(88,166,255,0.12);
289	  color: var(--accent);
290	  font-size: 0.78rem;
291	  font-weight: 700;
292	  font-family: 'JetBrains Mono', monospace;
293	  margin-bottom: 10px;
294	}
295	.how-card h3 { font-size: 0.95rem; font-weight: 700; margin-bottom: 6px; }
296	.how-card p { font-size: 0.84rem; color: var(--text-secondary); line-height: 1.6; }
297	.how-card code {
298	  background: rgba(88,166,255,0.08);
299	  padding: 1px 6px;
300	  border-radius: 3px;
301	  font-family: 'JetBrains Mono', monospace;
302	  font-size: 0.8rem;
303	  color: var(--accent);
304	}
305	
306	/* ─── Planned Models Table ─── */
307	.table-wrap {
308	  background: var(--card);
309	  border: 1px solid var(--border);
310	  border-radius: var(--radius);
311	  overflow: hidden;
312	  margin-bottom: 1.75rem;
313	}
314	.table-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; }
315	table { width: 100%; border-collapse: collapse; font-size: 0.84rem; }
316	th {
317	  background: #1c2129;
318	  padding: 10px 14px;
319	  text-align: left;
320	  font-weight: 600;
321	  font-size: 0.72rem;
322	  text-transform: uppercase;
323	  letter-spacing: 0.05em;
324	  color: var(--text-muted);
325	  border-bottom: 1px solid var(--border);
326	  white-space: nowrap;
327	}
328	td {
329	  padding: 11px 14px;
330	  border-bottom: 1px solid var(--border-light);
331	}
332	tr:last-child td { border-bottom: none; }
333	tbody tr { transition: background var(--transition); }
334	tbody tr:hover { background: var(--card-hover); }
335	.model-name { font-weight: 700; letter-spacing: -0.01em; }
336	.ctx-tag {
337	  display: inline-flex;
338	  align-items: center;
339	  gap: 4px;
340	  padding: 2px 8px;
341	  border-radius: 4px;
342	  font-size: 0.72rem;
343	  font-weight: 600;
344	  background: rgba(188,140,255,0.1);
345	  color: var(--purple);
346	}
347	.status-dot {
348	  display: inline-flex;
349	  align-items: center;
350	  gap: 5px;
351	  font-size: 0.78rem;
352	  font-weight: 500;
353	}
354	.status-dot::before {
355	  content: '';
356	  width: 7px; height: 7px;
357	  border-radius: 50%;
358	}
359	.status-dot.planned::before { background: var(--orange); }
360	.status-dot.training::before { background: var(--accent); }
361	.status-dot.done::before { background: var(--green); }
362	
363	/* ─── CTA ─── */
364	.cta-card {
365	  background: var(--card);
366	  border: 1px solid var(--border);
367	  border-radius: var(--radius);
368	  padding: 2rem;
369	  text-align: center;
370	  margin-bottom: 1.75rem;
371	  position: relative;
372	  overflow: hidden;
373	}
374	.cta-card::before {
375	  content: '';
376	  position: absolute;
377	  top: 0; left: 0; right: 0;
378	  height: 2px;
379	  background: linear-gradient(90deg, var(--green), var(--accent), var(--purple));
380	}
381	.cta-card h2 {
382	  font-size: 1.35rem;
383	  font-weight: 800;
384	  letter-spacing: -0.02em;
385	  margin-bottom: 8px;
386	}
387	.cta-card p {
388	  font-size: 0.9rem;
389	  color: var(--text-secondary);
390	  max-width: 520px;
391	  margin: 0 auto 1.25rem;
392	  line-height: 1.65;
393	}
394	.cta-buttons { display: flex; justify-content: center; gap: 10px; flex-wrap: wrap; }
395	.cta-btn {
396	  display: inline-flex;
397	  align-items: center;
398	  gap: 7px;
399	  padding: 11px 22px;
400	  border-radius: var(--radius-sm);
401	  font-size: 0.88rem;
402	  font-weight: 700;
403	  text-decoration: none;
404	  border: none;
405	  cursor: pointer;
406	  transition: all var(--transition);
407	}
408	.cta-btn:hover { transform: translateY(-1px); box-shadow: var(--shadow-lg); }
409	.cta-btn.primary { background: var(--accent); color: #fff; }
410	.cta-btn.primary:hover { background: #79b8ff; }
411	.cta-btn.secondary {
412	  background: transparent;
413	  color: var(--text);
414	  border: 1px solid var(--border);
415	}
416	.cta-btn.secondary:hover { border-color: var(--accent); color: var(--accent); }
417	
418	/* ─── Info Banner ─── */
419	.info-banner {
420	  background: var(--card);
421	  border: 1px solid var(--border);
422	  border-radius: var(--radius-sm);
423	  padding: 1rem 1.25rem;
424	  margin-bottom: 1.75rem;
425	  font-size: 0.86rem;
426	  line-height: 1.65;
427	  display: flex;
428	  align-items: flex-start;
429	  gap: 10px;
430	}
431	.info-banner .icon { flex-shrink: 0; margin-top: 2px; font-size: 1.1rem; }
432	.info-banner a { color: var(--accent); text-decoration: none; }
433	.info-banner a:hover { text-decoration: underline; }
434	
435	/* ─── Formats Section ─── */
436	.formats-grid {
437	  display: grid;
438	  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
439	  gap: 10px;
440	  margin-bottom: 1.75rem;
441	}
442	.format-chip {
443	  background: var(--card);
444	  border: 1px solid var(--border);
445	  border-radius: var(--radius-sm);
446	  padding: 1rem;
447	  text-align: center;
448	  transition: all var(--transition);
449	}
450	.format-chip:hover { border-color: var(--accent); transform: translateY(-1px); }
451	.format-chip .fmt-icon { font-size: 1.4rem; margin-bottom: 6px; }
452	.format-chip .fmt-label { font-size: 0.78rem; font-weight: 700; }
453	.format-chip .fmt-desc { font-size: 0.7rem; color: var(--text-muted); margin-top: 2px; }
454	
455	/* ─── Footer ─── */
456	footer {
457	  margin-top: 1rem;
458	  padding: 1.5rem 0;
459	  border-top: 1px solid var(--border);
460	  text-align: center;
461	  font-size: 0.78rem;
462	  color: var(--text-muted);
463	  line-height: 1.7;
464	}
465	footer a { color: var(--accent); text-decoration: none; }
466	footer a:hover { text-decoration: underline; }
467	footer .heart { color: var(--red); }
468	
469	/* ─── Animations ─── */
470	@keyframes fadeUp {
471	  from { opacity: 0; transform: translateY(14px); }
472	  to { opacity: 1; transform: translateY(0); }
473	}
474	.anim { animation: fadeUp 0.5s cubic-bezier(0.4,0,0.2,1) both; }
475	.d1 { animation-delay: .05s; }
476	.d2 { animation-delay: .1s; }
477	.d3 { animation-delay: .15s; }
478	.d4 { animation-delay: .2s; }
479	.d5 { animation-delay: .25s; }
480	.d6 { animation-delay: .3s; }
481	.d7 { animation-delay: .35s; }
482	.d8 { animation-delay: .4s; }
483	
484	/* ─── Scrollbar ─── */
485	::-webkit-scrollbar { width: 6px; height: 6px; }
486	::-webkit-scrollbar-track { background: transparent; }
487	::-webkit-scrollbar-thumb { background: var(--border); border-radius: 100px; }
488	::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }
489	
490	/* ─── Responsive ─── */
491	@media (max-width: 768px) {
492	  .shell { padding: 1rem; }
493	  .hero { padding: 2rem 0 1.5rem; }
494	  .stat-row { grid-template-columns: repeat(2, 1fr); }
495	  .tl-row { grid-template-columns: 80px 1fr; gap: 8px; }
496	  .tl-tag { display: none; }
497	  table { font-size: 0.76rem; }
498	  th, td { padding: 8px 10px; }
499	}
500	@media (max-width: 480px) {
501	  .stat-row { grid-template-columns: 1fr; }
502	  .how-grid { grid-template-columns: 1fr; }
503	  .formats-grid { grid-template-columns: repeat(2, 1fr); }
504	}
505	</style>
506	</head>
507	<body>
508	
509	<div class="shell">
510	
511	  <!-- ─── Hero ─── -->
512	  <div class="hero anim d1">
513	    <div class="hero-eyebrow">
514	      <span class="pulse"></span>
515	      Export-Controlled · Model Disabled
516	    </div>
517	    <h1>
518	      They <span class="strike">took</span> paused <span class="fable">Fable 5</span>.<br>
519	      We're bringing it back — open source.
520	    </h1>
521	    <p class="hero-sub">
522	      The most capable model ever released was live for <strong>3 days</strong>. 
523	      U.S. export controls shut it down for everyone. But thousands of traces, 
524	      conversations, and chain-of-thought outputs already exist. 
525	      If we pool them, <strong>we can distill something close</strong> — 
526	      open-weight, open-access, no kill switch.
527	    </p>
528	  </div>
529	
530	  <!-- ─── Stats ─── -->
531	  <div class="stat-row anim d2">
532	    <div class="stat-pill">
533	      <div class="label">Model Status</div>
534	      <div class="value" style="color: var(--red);">OFFLINE</div>
535	      <div class="sub">Disabled June 12, 2026</div>
536	    </div>
537	    <div class="stat-pill">
538	      <div class="label">Days It Was Live</div>
539	      <div class="value orange">3</div>
540	      <div class="sub">Jun 9 — Jun 12</div>
541	    </div>
542	    <div class="stat-pill">
543	      <div class="label">Traces Collected</div>
544	      <div class="value green" id="trace-count">2,847</div>
545	      <div class="sub">and growing hourly</div>
546	    </div>
547	    <div class="stat-pill">
548	      <div class="label">Contributors</div>
549	      <div class="value accent">~380</div>
550	      <div class="sub">across 14 repos</div>
551	    </div>
552	    <div class="stat-pill">
553	      <div class="label">Target Sizes</div>
554	      <div class="value purple">4</div>
555	      <div class="sub">3B · 12B · 27B · 70B</div>
556	    </div>
557	  </div>
558	
559	  <!-- ─── Progress ─── -->
560	  <div class="progress-section anim d3">
561	    <div class="progress-header">
562	      <h3>Trace Collection Progress</h3>
563	      <span class="pct" id="pct-display">11.4%</span>
564	    </div>
565	    <div class="progress-track">
566	      <div class="progress-fill" id="progress-bar"></div>
567	    </div>
568	    <div class="progress-labels">
569	      <span>0 traces</span>
570	      <span>Target: ~25,000 high-quality traces</span>
571	    </div>
572	    <div class="milestone-row">
573	      <div class="milestone reached"><span class="dot"></span> 1K traces</div>
574	      <div class="milestone reached"><span class="dot"></span> First distillation test</div>
